q=subprocess.run(args,capture_output=True,text=True,timeout=15);assert q.returncode==0,q.stderr
time.sleep(1)
status=subprocess.check_output(['systemctl','show',unit,'-p','ActiveState','-p','MainPID','-p','SubState'],text=True)
r={'status':'PASS_REVIEW_WAITER_STARTED','unit':unit,'source_sha256':'cc883807ae0cde2866ad7dba764687154cf6c86241c4f8160f76365400abb1ec','source_commit':'6d686687b3e5a4580936494ba244c5da187ee8d3','properties':status,'observation':b.observe()};b.save('WAITER_INSTALLED.json',r);print(json.dumps(r))
